import express from "express";

const app = express();

app.get("/healthz", (_req, res) => {
  res.json({ status: "ok" });
});

app.get("/busy", (_req, res) => {
  const end = Date.now() + 2000;
  while (Date.now() < end) {
    // two seconds of computing, with no await
  }
  res.json({ done: true });
});

app.get("/waiting", async (_req, res) => {
  await new Promise((resolve) => setTimeout(resolve, 2000));
  res.json({ done: true });
});

app.listen(Number(process.env.PORT ?? 4000), "127.0.0.1");
